   183	    // If we are handling an old dot Expensify link we need to open it with openOldDotLink() so we can navigate to it with the user already logged in.
   184	    // As attachments also use expensify.com we don't want it working the same as links.
   185	    if (internalExpensifyPath && !isAttachment) {
   186	        openOldDotLink(internalExpensifyPath);
   187	        return;
   188	    }
   189	
   190	    openExternalLink(href);
